def _depurar_duplicados(apps, schema_editor):
    """
    Antes de crear las restricciones de unicidad se consolidan los
    registros duplicados que pudieran existir en la base real.

    * Ciudad: se conserva la primera de cada (provincia, nombre) y se
      reasignan los datos de nacimiento y secundario que la usaban.
    * DatosNacimiento y Secundario: uno por graduado (se conserva el
      más completo).
    * Titulo: uno por (carrera, nombre).
    """

    Ciudad = apps.get_model("academico", "Ciudad")
    DatosNacimiento = apps.get_model("academico", "DatosNacimiento")
    Secundario = apps.get_model("academico", "Secundario")
    Titulo = apps.get_model("academico", "Titulo")

    # --- Ciudades duplicadas dentro de una misma provincia.
    vistos = {}

    for ciudad in Ciudad.objects.order_by("id_ciudad"):
        clave = (ciudad.id_provincia_id, ciudad.nombre_ciudad.strip().lower())

        if clave not in vistos:
            vistos[clave] = ciudad.id_ciudad
            continue

        conservada = vistos[clave]

        DatosNacimiento.objects.filter(id_ciudad_id=ciudad.id_ciudad).update(
            id_ciudad_id=conservada
        )
        Secundario.objects.filter(id_ciudad_id=ciudad.id_ciudad).update(
            id_ciudad_id=conservada
        )
        ciudad.delete()

    def _puntaje(registro, campos):
        return sum(
            1 for campo in campos if getattr(registro, campo, None) is not None
        )

    # --- Datos de nacimiento duplicados.
    por_legajo = {}

    for datos in DatosNacimiento.objects.order_by("id_datos"):
        por_legajo.setdefault(datos.legajo_graduado_id, []).append(datos)

    for registros in por_legajo.values():
        if len(registros) < 2:
            continue

        registros.sort(
            key=lambda r: (
                -_puntaje(r, ("fecha_nacimiento", "id_provincia_id", "id_ciudad_id")),
                r.id_datos,
            )
        )

        for sobrante in registros[1:]:
            sobrante.delete()

    # --- Secundario duplicados.
    por_legajo = {}

    for secundario in Secundario.objects.order_by("id_secundario"):
        por_legajo.setdefault(
            secundario.legajo_graduado_id, []
        ).append(secundario)

    for registros in por_legajo.values():
        if len(registros) < 2:
            continue

        registros.sort(
            key=lambda r: (
                -_puntaje(
                    r,
                    (
                        "nombre_secundario",
                        "titulo_secundario",
                        "id_provincia_id",
                        "id_ciudad_id",
                        "anio_egreso_secundario",
                    ),
                ),
                r.id_secundario,
            )
        )

        for sobrante in registros[1:]:
            sobrante.delete()

    # --- Títulos duplicados por carrera.
    vistos = set()

    for titulo in Titulo.objects.order_by("id_titulo"):
        clave = (titulo.codigo_carrera_id, titulo.nombre_titulo.strip().lower())

        if clave in vistos:
            titulo.delete()
        else:
            vistos.add(clave)


